def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    if n == 99:
        return 'D'

    opp_c = opp.count('C')
    opp_d = n - opp_c

    if opp_c == 0:
        return 'D'

    cd = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'C' and opp[i] == 'D':
            cd += 1
        else:
            break

    run_c = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            run_c += 1
        else:
            break

    run_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            run_d += 1
        else:
            break

    exploit = 0
    punish = 0
    for i in range(1, n):
        if me[i - 1] == 'D' and opp[i - 1] == 'C':
            exploit += 1
            if opp[i] == 'D':
                punish += 1

    if exploit >= 1 and punish == 0 and run_c >= 5:
        return 'D'

    if last_opp == 'D':
        if run_d >= 6:
            return 'D'

        if (
            n >= 2
            and last_me == 'C'
            and me[-2] == 'D'
            and opp[-2] == 'D'
        ):
            return 'D'

        if (
            n >= 3
            and last_me == 'D'
            and me[-2] == 'C'
            and opp[-2] == 'D'
            and me[-3] == 'D'
            and opp[-3] == 'D'
        ):
            return 'D'

        if cd >= 2:
            return 'D'

        if (
            n >= 3
            and cd >= 1
            and opp[-3] == 'D'
            and opp[-2] == 'D'
            and opp[-1] == 'D'
        ):
            return 'D'

        if last_me == 'D':
            return 'C'

        return 'C'

    if last_me == 'D':
        return 'C'

    if run_c >= 15 and opp_d == 0 and exploit == 0:
        return 'D'

    if run_c >= 25 and n >= 40 and exploit == 0 and opp_d <= 2 and rng.random() < 0.02:
        return 'D'

    return 'C'
